import re

UNIT_SECONDS = {
    's': 1, 'sec': 1, 'secs': 1, 'second': 1, 'seconds': 1,
    'm': 60, 'min': 60, 'mins': 60, 'minute': 60, 'minutes': 60,
    'h': 3600, 'hr': 3600, 'hrs': 3600, 'hour': 3600, 'hours': 3600,
    'd': 86400, 'day': 86400, 'days': 86400,
    'w': 604800, 'week': 604800, 'weeks': 604800,
}

ISO_UNIT_SECONDS = {
    'W': 604800,
    'D': 86400,
    'H': 3600,
    'M': 60,
    'S': 1,
}


def parse_duration(text: str) -> int:
    """Return the duration described by `text` in whole seconds. See README.md."""
    if text is None:
        raise ValueError("empty input")
    s = text.strip()
    if not s:
        raise ValueError("empty input")

    # bare integer
    if re.fullmatch(r'\d+', s):
        value = int(s)
        return value

    # ISO 8601 duration
    if s[0] == 'P':
        return _parse_iso8601(s)

    # clock notation: hh:mm:ss or mm:ss
    if ':' in s:
        return _parse_clock(s)

    # number+unit components
    return _parse_components(s)


def _parse_clock(s: str) -> int:
    parts = s.split(':')
    if len(parts) not in (2, 3):
        raise ValueError(f"invalid clock duration: {text!r}" if False else f"invalid clock duration: {s!r}")
    for p in parts:
        if not re.fullmatch(r'\d+', p):
            raise ValueError(f"invalid clock duration: {s!r}")
    nums = [int(p) for p in parts]
    if len(nums) == 3:
        h, m, sec = nums
    else:
        h = 0
        m, sec = nums
    total = h * 3600 + m * 60 + sec
    return total


def _parse_iso8601(s: str) -> int:
    pattern = re.compile(
        r'^P(?:(?P<weeks>\d+(?:\.\d+)?)W)?'
        r'(?:(?P<days>\d+(?:\.\d+)?)D)?'
        r'(?:T(?:(?P<hours>\d+(?:\.\d+)?)H)?'
        r'(?:(?P<minutes>\d+(?:\.\d+)?)M)?'
        r'(?:(?P<seconds>\d+(?:\.\d+)?)S)?)?$'
    )
    m = pattern.match(s)
    if not m or not any(m.groupdict().values()):
        raise ValueError(f"invalid ISO 8601 duration: {s!r}")
    total = 0.0
    groups = m.groupdict()
    unit_map = {
        'weeks': 604800,
        'days': 86400,
        'hours': 3600,
        'minutes': 60,
        'seconds': 1,
    }
    for key, seconds_per_unit in unit_map.items():
        val = groups.get(key)
        if val is not None:
            total += float(val) * seconds_per_unit
    return round(total)


def _parse_components(s: str) -> int:
    # Normalize spaces, but keep letters/numbers grouped
    pattern = re.compile(r'(\d+(?:\.\d+)?)\s*([a-zA-Z]+)')
    pos = 0
    total = 0.0
    found_any = False
    # remove whitespace between number and following text is handled by pattern already
    # We need to ensure entire string is consumed by matches separated only by spaces
    remaining = s
    idx = 0
    matches = list(pattern.finditer(s))
    if not matches:
        raise ValueError(f"invalid duration: {s!r}")
    # verify that the matches cover the whole string except for whitespace
    cursor = 0
    for match in matches:
        gap = s[cursor:match.start()]
        if gap.strip() != '':
            raise ValueError(f"invalid duration: {s!r}")
        cursor = match.end()
    trailing = s[cursor:]
    if trailing.strip() != '':
        raise ValueError(f"invalid duration: {s!r}")

    for match in matches:
        num_str, unit_str = match.groups()
        unit_key = unit_str.lower()
        if unit_key not in UNIT_SECONDS:
            raise ValueError(f"unknown unit: {unit_str!r}")
        total += float(num_str) * UNIT_SECONDS[unit_key]
        found_any = True

    if not found_any:
        raise ValueError(f"invalid duration: {s!r}")

    return round(total)

